import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={front:new URL('./reference-redraw-front.png',import.meta.url).href,back:new URL('./reference-redraw-back.png',import.meta.url).href};export function addStickers(host,{frontCover=true}={}){const layers=[];for(const face of frontCover?['front','back']:['back']){const v=spec.labels[face],position=[...v.position];if(face==='front')position[2]+=.05;layers.push(...printedArtwork(host,{target:host.hbridgeAssembly.labels[face],url:sources[face],size:v.size,position,face,depth:.1,name:'Original U160 '+face+' body-label official-reference redraw',artworkKind:'reference-redraw'})??[]);}return layers;}
